{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Compassionate therapy in {{CITY}}, {{STATE}} — support for anxiety, trauma, relationships, life transitions and burnout.">
  <link rel="icon" href="data:;base64,iVBORw0KGgo=">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-earthy">
  <header class="site-header">
    <div class="container nav-row">
      <div class="brand">
        <a href="index.html" aria-label="Home"><svg class="logo" viewBox="0 0 120 32" xmlns="http://www.w3.org/2000/svg"><rect fill="#6B4F3A" width="120" height="32" rx="6"/><text x="14" y="21" font-size="12" fill="#FFF" font-family="Arial, Helvetica, sans-serif">{{BUSINESS_NAME}}</text></svg></a>
        <button id="mobile-nav-toggle" aria-label="Toggle navigation">☰</button>
      </div>
      <nav class="main-nav" id="main-nav">
        <a href="about.html">About</a>
        <a href="specialties.html">Specialties</a>
        <a href="approach.html">Approach</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">FAQ</a>
        <a href="book.html" class="cta">Work With Me</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero" id="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1 class="eyebrow">Therapy that meets you where you are</h1>
          <h2 class="title">A calm, steady space to work through what matters most</h2>
          <p class="lead">I’m {{THERAPIST_NAME}}, a licensed therapist ({{LICENSE}}). I help adults and couples navigate anxiety, trauma recovery, relationship shifts, and burnout with pragmatic compassion and evidence-informed tools.</p>
          <div class="hero-cta">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button class="btn ghost" id="open-lead">Get a free guide</button>
          </div>
          <ul class="quick-list">
            <li>Sessions in-person in {{CITY}}, {{STATE}} &amp; telehealth</li>
            <li>Private, confidential care</li>
            <li>Sliding scale &amp; limited evening hours</li>
          </ul>
        </div>
        <div class="hero-art">
          <img src="assets/img/hero.svg" alt="Illustration of gentle landscape" class="hero-illustration">
          <div class="therapist-card">
            <img src="assets/img/avatar.svg" alt="Avatar of {{THERAPIST_NAME}}" class="avatar">
            <div>
              <div class="name">{{THERAPIST_NAME}}, {{LICENSE}}</div>
              <div class="modalities">Modalities: {{MODALITIES}}</div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof container" id="social-proof">
      <h3 class="section-heading">Trusted care — real feedback</h3>
      <div class="testimonials">
        <blockquote class="testimonial">
          “I felt heard from our very first session. Practical tools and gentle guidance helped me sleep and trust myself again.”
          <cite>— A. (client)</cite>
        </blockquote>
        <blockquote class="testimonial">
          “Clear goals, kind boundaries, and steady presence. I recommend {{THERAPIST_NAME}} to friends facing big life changes.”
          <cite>— M. (client)</cite>
        </blockquote>
      </div>
      <div class="trust-logos">
        <span class="pill">Telehealth</span>
        <span class="pill">HIPAA-compliant</span>
        <span class="pill">Private practice</span>
      </div>
    </section>

    <!-- BENEFITS -->
    <section class="benefits container" id="benefits">
      <h3 class="section-heading">What people gain in therapy here</h3>
      <div class="cards">
        <article class="card">
          <h4>Tools for daily life</h4>
          <p>Practical strategies you can use between sessions to manage anxiety and overwhelm.</p>
        </article>
        <article class="card">
          <h4>Safer processing</h4>
          <p>Trauma-aware pacing so you feel contained while exploring difficult memories.</p>
        </article>
        <article class="card">
          <h4>Stronger relationships</h4>
          <p>Communication and boundary work to rebuild trust and deepen connection.</p>
        </article>
        <article class="card">
          <h4>Clearer values</h4>
          <p>Support for life transitions—career decisions, new parenthood, or endings—aligned with your priorities.</p>
        </article>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process container" id="process">
      <h3 class="section-heading">How working together usually unfolds</h3>
      <ol class="steps">
        <li>
          <strong>Reach out</strong>
          <p>We’ll connect by phone or email to review needs, availability, and insurance/fees.</p>
        </li>
        <li>
          <strong>Intake session</strong>
          <p>We gather history and co-create a modest treatment plan with goals you choose.</p>
        </li>
        <li>
          <strong>Ongoing work</strong>
          <p>Weekly or biweekly sessions that blend skills, insight, and somatic awareness.</p>
        </li>
        <li>
          <strong>Review &amp; goals</strong>
          <p>We periodically check progress and update the plan as life changes.</p>
        </li>
      </ol>
    </section>

    <!-- FAQ (small) -->
    <section class="faq container" id="faq">
      <h3 class="section-heading">Common questions</h3>
      <div class="accordion">
        <button class="acc-toggle" aria-expanded="false">Do you accept insurance?</button>
        <div class="acc-panel">I am an out-of-network provider. I provide superbills you may submit to your insurer. Sliding scale is available for limited spots.</div>
        <button class="acc-toggle" aria-expanded="false">What if I’m in crisis?</button>
        <div class="acc-panel">If you are experiencing a crisis or are in danger, call emergency services or go to your nearest emergency room. For urgent concerns, contact local crisis lines. Therapy here is not a crisis service.</div>
        <button class="acc-toggle" aria-expanded="false">How long will therapy take?</button>
        <div class="acc-panel">Duration varies. Some clients come for a short term to address a specific issue; others prefer longer-term work. We set goals together and regularly review progress.</div>
      </div>
      <p class="note">If you don’t see your question answered, email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>

    <!-- LEAD MAGNET -->
    <section class="lead-magnet container" id="lead-magnet">
      <div class="lead-inner">
        <div>
          <h3 class="section-heading">Free resource: A gentle guide to managing anxious overwhelm</h3>
          <p>Short, practical steps you can try tonight. No cost, no pressure—just a resource to keep.</p>
        </div>
        <form id="lead-form" class="lead-form" aria-label="Download guide">
          <label for="lead-email">Email</label>
          <input id="lead-email" name="email" type="email" placeholder="you@example.com" required>
          <button class="btn primary" type="submit">Send me the guide</button>
        </form>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta container" id="final-cta">
      <div class="cta-inner">
        <div>
          <h3>Ready to begin?</h3>
          <p>Schedule a 20-minute consultation to see if we’re a fit. Confidential, judgment-free conversation.</p>
        </div>
        <div class="cta-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="contact.html">Contact</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>
          <div>{{THERAPIST_NAME}}, {{LICENSE}}</div>
          <div>{{CITY}}, {{STATE}}</div>
          <div><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </address>
      </div>
      <div class="footer-links">
        <a href="privacy.html">Privacy</a>
        <a href="faq.html">FAQ</a>
        <a href="contact.html">Contact</a>
      </div>
    </div>
    <div class="legal container">
      <p>Confidentiality note: Sessions are private and HIPAA-compliant where applicable. This site is informational and not a substitute for medical care. If you are in crisis, call emergency services or local crisis lines immediately. Therapy scope: I work with adults on anxiety, trauma, relationship concerns, life transitions and burnout.</p>
      <p class="license">License: {{LICENSE}}</p>
    </div>
  </footer>

  <!-- Modal for lead magnet confirmation -->
  <div id="modal" class="modal" aria-hidden="true">
    <div class="modal-content" role="dialog" aria-modal="true">
      <button class="modal-close" id="modal-close" aria-label="Close">×</button>
      <h4>Thanks — your guide is on its way</h4>
      <p>Check your inbox. If you don’t see it, check promotions or spam. You can also contact <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Book a consult</a>
    </div>
  </div>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
