{"path":"assets/css/styles.css","content":"/* Earthy warm theme styles */
:root{
  --bg:#FBF8F4;
  --muted:#8B7D72;
  --accent:#7A5A42;
  --accent-2:#C4AD95;
  --card:#FFF8F4;
  --text:#2E2A27;
  --radius:12px;
}
*{box-sizing:border-box}
body{margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;background:var(--bg);color:var(--text);line-height:1.5}
.container{max-width:980px;margin:0 auto;padding:28px}
.site-header{background:linear-gradient(180deg,rgba(122,90,66,0.06),transparent);border-bottom:1px solid rgba(122,90,66,0.06)}
.nav-row{display:flex;align-items:center;justify-content:space-between;padding:18px 0}
.brand{display:flex;align-items:center;gap:12px}
.brand .logo{width:160px;height:32px}
#mobile-nav-toggle{display:none;background:none;border:0;font-size:20px}
.main-nav{display:flex;gap:16px;align-items:center}
.main-nav a{color:var(--muted);text-decoration:none;padding:8px;border-radius:8px}
.main-nav a.cta{background:var(--accent);color:#fff;padding:10px 14px}
.hero{padding:36px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
.eyebrow{color:var(--accent-2);font-weight:600;margin:0}
.title{font-size:28px;margin:8px 0 12px}
.lead{color:var(--muted);margin:0 0 16px}
.hero-cta{display:flex;gap:12px;margin-bottom:12px}
.btn{display:inline-block;border:0;padding:10px 14px;border-radius:10px;cursor:pointer;text-decoration:none}
.btn.primary{background:var(--accent);color:#fff}
.btn.ghost{background:transparent;border:1px solid rgba(122,90,66,0.12);color:var(--accent)}
.quick-list{list-style:none;padding:0;margin:12px 0 0;color:var(--muted)}
.hero-art{position:relative}
.hero-illustration{width:100%;border-radius:14px;box-shadow:0 6px 18px rgba(46,42,39,0.06)}
.therapist-card{position:absolute;left:18px;bottom:-28px;background:var(--card);padding:10px;border-radius:12px;display:flex;gap:10px;align-items:center;box-shadow:0 10px 30px rgba(46,42,39,0.06)}
.avatar{width:56px;height:56px;border-radius:50%;background:#fff}
.name{font-weight:700}
.modalities{font-size:13px;color:var(--muted)}
.social-proof{padding:32px 0}
.section-heading{margin:0 0 18px;font-size:18px;color:var(--accent)}
.testimonials{display:flex;gap:12px}
.testimonial{background:linear-gradient(180deg, rgba(196,173,149,0.08), transparent);padding:16px;border-radius:12px;flex:1}
.testimonial cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}
.trust-logos{margin-top:12px}
.pill{display:inline-block;background:var(--card);padding:6px 10px;border-radius:999px;margin-right:8px;color:var(--muted);font-size:13px}
.benefits{padding:30px 0}
.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.card{background:var(--card);padding:16px;border-radius:12px}
.process{padding:30px 0}
.steps{counter-reset:step;list-style:none;padding:0;margin:0}
.steps li{background:white;padding:14px;border-radius:12px;margin-bottom:12px;display:flex;gap:12px}
.steps li strong{display:block;width:160px;color:var(--accent)}
.faq{padding:24px 0}
.accordion{display:block}
.acc-toggle{width:100%;text-align:left;padding:12px;border:0;background:linear-gradient(180deg,transparent,transparent);border-radius:10px;margin-bottom:6px}
.acc-panel{padding:8px 12px;margin-bottom:10px;background:var(--card);border-radius:10px;display:none}
.lead-magnet{background:linear-gradient(180deg,rgba(122,90,66,0.03),transparent);padding:20px;border-radius:12px;margin:20px 0}
.lead-inner{display:flex;gap:16px;align-items:center;justify-content:space-between}
.lead-form{display:flex;gap:8px;align-items:center}
.lead-form input{padding:10px;border-radius:8px;border:1px solid rgba(46,42,39,0.08)}
.final-cta{padding:26px 0}
.cta-inner{display:flex;align-items:center;justify-content:space-between}
.footer-grid{display:flex;justify-content:space-between;align-items:flex-start;padding:18px 0}
.footer-links a{display:block;color:var(--muted);text-decoration:none;margin-bottom:6px}
.legal{font-size:13px;color:var(--muted);padding-bottom:28px}
.modal{position:fixed;inset:0;background:rgba(18,16,14,0.4);display:none;align-items:center;justify-content:center}
.modal-content{background:#fff;padding:22px;border-radius:12px;max-width:520px}
.modal-close{background:none;border:0;position:absolute;right:22px;top:22px;font-size:20px}
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  #mobile-nav-toggle{display:inline-block}
  .main-nav{display:none;flex-direction:column;background:transparent;padding:12px}
  .testimonials{flex-direction:column}
  .cards{grid-template-columns:1fr}
  .lead-inner{flex-direction:column;align-items:flex-start}
  .cta-inner{flex-direction:column;align-items:flex-start}
}
"} 
{"path":"assets/js/main.js","content":"// Basic interactivity: mobile nav, modal, lead form, accordion
document.addEventListener('DOMContentLoaded',function(){
  var mobileToggle = document.getElementById('mobile-nav-toggle');
  var mainNav = document.getElementById('main-nav');
  if(mobileToggle&&mainNav){
    mobileToggle.addEventListener('click',function(){
      mainNav.style.display = mainNav.style.display === 'flex' ? 'none' : 'flex';
    });
  }

  var openLead = document.getElementById('open-lead');
  var modal = document.getElementById('modal');
  var modalClose = document.getElementById('modal-close');
  var leadForm = document.getElementById('lead-form');

  function showModal(){
    if(modal){modal.style.display='flex';modal.setAttribute('aria-hidden','false');}
  }
  function hideModal(){
    if(modal){modal.style.display='none';modal.setAttribute('aria-hidden','true');}
  }
  if(openLead){openLead.addEventListener('click',showModal);} 
  if(modalClose){modalClose.addEventListener('click',hideModal);} 
  if(modal){modal.addEventListener('click',function(e){if(e.target===modal)hideModal();});}

  if(leadForm){
    leadForm.addEventListener('submit',function(e){
      e.preventDefault();
      var email = document.getElementById('lead-email').value || '';
      // Simple validation
      if(!email || email.indexOf('@')===-1){
        alert('Please enter a valid email');
        return;
      }
      // Pretend to send — in real site replace with API
      showModal();
    });
  }

  // Accordion toggles
  var toggles = document.querySelectorAll('.acc-toggle');
  toggles.forEach(function(btn){
    btn.addEventListener('click',function(){
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', String(!expanded));
      var panel = btn.nextElementSibling;
      if(panel){ panel.style.display = expanded ? 'none' : 'block'; }
    });
  });
});
"} 
